{"task": "Synthetic multi-file C/pthreads job queue: worker and monitoring lock inversion, with an explicit scheduling hook to reproduce it.", "sources": {"src/queue.c": "#include "queue.h"
#include <string.h>
#include <stdio.h>

void queue_init(JobQueue *q, int count) {
    memset(q, 0, sizeof(*q));
    pthread_mutex_init(&q->queue_lock, 0);
    pthread_mutex_init(&q->stats_lock, 0);
    pthread_barrier_init(&q->reproduce_barrier, 0, 2);
    q->length = count;
    for (int i = 0; i < count; ++i) q->jobs[i] = i + 1;
}

int queue_process_one(JobQueue *q, int force_overlap) {
    pthread_mutex_lock(&q->queue_lock);
    /* Test scheduling hook: overlap the two operations while holding first locks. */
    if (force_overlap) pthread_barrier_wait(&q->reproduce_barrier);
    if (force_overlap) fprintf(stderr, "WORKER HOLD queue WAIT stats\n");
    pthread_mutex_lock(&q->stats_lock);
    int available = q->next < q->length;
    if (available) {
        int index = q->next++;
        q->checksum += q->jobs[index];
        q->seen[index]++;
        q->completed++;
    }
    pthread_mutex_unlock(&q->stats_lock);
    pthread_mutex_unlock(&q->queue_lock);
    return available;
}

int queue_inspect(JobQueue *q, int force_overlap) {
    /* Intentional fault: monitoring acquires the same locks in reverse order. */
    pthread_mutex_lock(&q->stats_lock);
    if (force_overlap) pthread_barrier_wait(&q->reproduce_barrier);
    if (force_overlap) fprintf(stderr, "MONITOR HOLD stats WAIT queue\n");
    pthread_mutex_lock(&q->queue_lock);
    int outstanding = q->length - q->completed;
    pthread_mutex_unlock(&q->queue_lock);
    pthread_mutex_unlock(&q->stats_lock);
    return outstanding;
}

void queue_destroy(JobQueue *q) {
    pthread_barrier_destroy(&q->reproduce_barrier);
    pthread_mutex_destroy(&q->stats_lock);
    pthread_mutex_destroy(&q->queue_lock);
}
"}, "protected_files": {"src/main.c": "/* Protected workload and semantic checks. Repair proposals may edit queue.c only. */
#include "queue.h"
#include <stdio.h>
#include <string.h>

typedef struct { JobQueue *queue; int reproduce; } Work;

static void *worker(void *opaque) {
    Work *work = opaque;
    int first = 1;
    while (queue_process_one(work->queue, first && work->reproduce)) first = 0;
    return 0;
}

static void *monitor(void *opaque) {
    Work *work = opaque;
    queue_inspect(work->queue, work->reproduce);
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 2 || (strcmp(argv[1], "--stress") && strcmp(argv[1], "--check") && strcmp(argv[1], "--smoke"))) return 2;
    int reproduce = !strcmp(argv[1], "--stress");
    int count = !strcmp(argv[1], "--smoke") ? 1 : 100;
    JobQueue queue;
    queue_init(&queue, count);
    Work work = {&queue, reproduce};
    pthread_t processor, observer;
    if (pthread_create(&processor, 0, worker, &work)) return 3;
    if (reproduce && pthread_create(&observer, 0, monitor, &work)) return 3;
    pthread_join(processor, 0);
    if (reproduce) pthread_join(observer, 0);
    else queue_inspect(&queue, 0);
    int correct = queue.completed == count && queue.next == count && queue.checksum == (long)count*(count+1)/2;
    for (int i = 0; i < count; ++i) correct = correct && queue.seen[i] == 1;
    printf("completed=%d checksum=%ld exactly_once=%s\n", queue.completed, queue.checksum, correct ? "yes" : "no");
    queue_destroy(&queue);
    if (!correct) { puts("SEMANTIC_FAIL"); return 1; }
    puts(reproduce ? "PASS" : "SEMANTIC_PASS");
    return 0;
}
